export default {"version":"1.0.0","source":{"title":"Inside the Wordscapes Daily Puzzles: The Secret Calendar","url":"https://www.solvingwordscapes.com/wordscapes-daily-puzzles-study/","author":"Pop (Solving Wordscapes)","published":"2026-08-11","updated":"2026-09-01"},"todaysAnswerUrl":"https://www.solvingwordscapes.com/category/daily/","notes":["The Wordscapes Daily Puzzle runs on a fixed 366-slot calendar: the same date brings back the same puzzle every year.","This file holds dates and the facts the study publishes about them. It deliberately contains no letters, no grids and no answer lists."],"flaggedDays":{"description":"36 dailies a year carry an internal marker in the game data. It does not mean harder: flagged boards lean a touch friendlier. What the flag means is still an open question.","defaultDays":[14,15,19],"overrides":{"6":[14,19,24]},"overrideReason":"The birthday week moved from June 11-16 (2024 event) to June 19-24; the flags travelled with their puzzles, so June is flagged on the 14th, 19th and 24th."},"specialDays":[{"date":"01-01","kind":"accident","word":"CLOVER","title":"New Year's Day serves CLOVER","summary":"Lucky-sounding, but nothing else in the base calendar suggests it is intentional."},{"date":"01-15","kind":"record","word":"SEXISM","title":"One of the two quietest regular dailies","summary":"Only 8 words placed, the minimum for a regular daily. Also a flagged day."},{"date":"02-14","kind":"accident","word":"SURVIVE","title":"Valentine's Day serves SURVIVE","summary":"Either an accident or the most honest puzzle in the game."},{"date":"02-15","kind":"record","word":"WAYWARD","title":"One of the two quietest regular dailies","summary":"Only 8 words placed, the minimum for a regular daily. Also a flagged day."},{"date":"02-29","kind":"rarest","word":"ASSAULT","title":"The rarest daily in Wordscapes","summary":"Served once every four years. If you play it, you are playing the least played puzzle in the game.","pageUrl":"https://www.solvingwordscapes.com/february-29/"},{"date":"03-17","kind":"accident","word":"COLONEL","title":"St. Patrick's Day serves COLONEL","summary":"The base calendar was filled without looking at the holidays."},{"date":"04-01","kind":"prank","word":"JOKER","title":"April Fools: every word is written backwards","summary":"A 5-letter rack, 6 words and the smallest board of the year. Swipe in a mirror. The previous version of the prank was REFLECT.","pageUrl":"https://www.solvingwordscapes.com/april-1/"},{"date":"06-10","kind":"joke","word":"PET ROCK","title":"The pet rock","summary":"Seven letters from which no 7-letter English word exists. They spell PET ROCK, the opener of the June 2024 birthday event. The best you can do is ROCKET or POCKET."},{"date":"06-19","kind":"birthday","word":"BIRTHDAY","title":"Birthday week, day 1: BIRTHDAY","summary":"An 8-letter rack, a format that exists nowhere else in the game. In 2024 this puzzle ran on June 14, the real launch anniversary.","pageUrl":"https://www.solvingwordscapes.com/june-19/"},{"date":"06-20","kind":"birthday","word":"OBSERVE","title":"Birthday week, day 2: OBSERVE","summary":"The busiest daily of the year: 19 words on one board. A wink at the Wildlife feature."},{"date":"06-21","kind":"birthday","word":"WILDLIFE","title":"Birthday week, day 3: WILDLIFE","summary":"An 8-letter rack naming the game's animal collection feature."},{"date":"06-22","kind":"birthday","word":"FORTUNE","title":"Birthday week, day 4: FORTUNE","summary":"A wink at Mt. Fortune. One of the three 16x12 boards, the biggest of the year. Not part of the 2024 event; added when the week became permanent."},{"date":"06-23","kind":"birthday","word":"CROSSWORD","title":"Birthday week, day 5: CROSSWORD","summary":"Nine letters, the longest word ever placed in a daily, on a 16x12 board."},{"date":"06-24","kind":"birthday","word":"WORD GAME","title":"Birthday week, day 6: the rack spells WORD GAME","summary":"Eight letters that rearrange into WORD GAME, which the game cannot place. The longest playable word is MEADOW. Also a flagged day."},{"date":"07-04","kind":"accident","word":"THROAT","title":"Fourth of July serves THROAT","summary":"The base calendar has no idea what day it is."},{"date":"11-11","kind":"accident","word":"RETIREE","title":"Veterans Day serves RETIREE","summary":"The only date in the base calendar where the word and the day even come close. Probably still an accident."},{"date":"12-21","kind":"accident","word":"FINANCE","title":"National Crossword Puzzle Day serves FINANCE","summary":"A crossword game had exactly one date to nail, the anniversary of the first crossword (1913). It serves FINANCE."},{"date":"12-26","kind":"holiday","word":"MENORAH","title":"The only holiday-themed daily of the year","summary":"Pinned to a fixed date even though Hanukkah moves. The lone survivor of the December 2024 holiday event.","pageUrl":"https://www.solvingwordscapes.com/december-26/"}],"kinds":{"prank":{"label":"Prank day","special":true},"birthday":{"label":"Birthday week","special":true},"holiday":{"label":"Holiday daily","special":true},"rarest":{"label":"Rarest daily","special":true},"joke":{"label":"Designer joke","special":true},"record":{"label":"Calendar record","special":true},"accident":{"label":"Calendar accident","special":false},"flagged":{"label":"Flagged day","special":true}}};
